package com.bank.compare;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class ArrayVsLinkedDemo {
    private static final Logger log = Logger.getLogger(ArrayVsLinkedDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        // Array: fast O(1) access by index
        BigDecimal[] amounts = {
            new BigDecimal("1000.00"),
            new BigDecimal("2000.00"),
            new BigDecimal("3000.00")
        };
        ArrayBackedStatement stmt = new ArrayBackedStatement(amounts);
        log.info(() -> "Array access index 2 (O(1)): Rs." + stmt.get(2));

        // Linked list: fast O(1) head insertion
        LinkedPendingQueue queue = new LinkedPendingQueue();
        queue.addFront(new BigDecimal("500.00"));
        queue.addFront(new BigDecimal("750.00"));
        log.info(() -> "Linked head after O(1) inserts: Rs." + queue.peekHead());
    }
}

class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
