package com.bank.compare;

import java.math.BigDecimal;

class LinkedPendingQueue {
    private Node head;

    // O(1) head insertion: no shifting, just re-point references.
    void addFront(BigDecimal amount) {
        Node node = new Node(amount);
        node.next = head;
        head = node;
    }

    BigDecimal peekHead() {
        if (head == null) throw new IllegalStateException("queue empty");
        return head.amount;
    }
}
